import{_ as t}from"./chunks/diagram_procesu1.Cry2C4TX.js";import{_ as r,o,c as i,aa as s}from"./chunks/framework.BAs_AphD.js";const u=JSON.parse('{"title":"Process Description","description":"","frontmatter":{"title":"Process Description","wiki":"en:performedworks:contractor_description"},"headers":[],"relativePath":"en/performedworks/contractor_description.md","filePath":"en/performedworks/contractor_description.md","lastUpdated":1794388980000}'),a={name:"en/performedworks/contractor_description.md"};function n(p,e,c,d,h,l){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="process-description" tabindex="-1">Process Description <a class="header-anchor" href="#process-description" aria-label="Permalink to &quot;Process Description&quot;">​</a></h1><p>This process is used to enter and approve work statements prepared by the Contractor Representative and approved by the Client Representative.</p><p>The workflow is illustrated in the following diagram:</p><img src="'+t+'" alt="" width="900" loading="lazy"><h2 id="the-process-consists-of-the-following-steps" tabindex="-1">The process consists of the following steps: <a class="header-anchor" href="#the-process-consists-of-the-following-steps" aria-label="Permalink to &quot;The process consists of the following steps:&quot;">​</a></h2><ol><li><p>The Project Administrator creates a new period for entering Performed Works. The Contractor Representative is notified by email that they can enter work statements for the given period.</p></li><li><p>The Contractor Representative fills in the Proposed Quantities for individual budget items for the given period. Once the proposal is complete, they submit the Measurement Report for approval by the Client Representative. The Client Representative is notified by email that the SPP has been prepared by the contractor and is ready for approval.</p></li><li><p>The Client Representative reviews the entries and changes the status of the items as appropriate. This can be done individually or in bulk. Items can be approved as proposed, their quantities can be changed, or the proposed quantity for an item can be rejected entirely. If the Client Representative does not want to close an item, they change its status to In Negotiation. Once the Client Representative considers all items resolved, they can approve and lock the Measurement Report for the given period. If any items remain In Negotiation, the Measurement Report is returned to the Contractor Representative for changes. Comments can be added to individual items. The Contractor Representative is notified by email that changes need to be made to the SPP.</p></li><li><p>For items with the status In Negotiation, the Contractor Representative enters a new proposed quantity and submits the revised Measurement Report for approval. The Client Representative is notified by email.</p></li><li><p>The Client Representative repeats the procedure described in step 3 for items with the status In Negotiation.</p></li><li><p>Once the Client Representative approves and thereby locks the Measurement Report, the Contractor Representative receives an email with the Measurement Report for the given period as an attachment. The report is automatically generated by the system and electronically signed. The contractor should use this PDF document as the basis for issuing an invoice and attach it to the invoice either electronically or in printed form.</p></li></ol>',6)])])}const v=r(a,[["render",n]]);export{u as __pageData,v as default};
